WITH lines AS (SELECT c.id, c.customer_id, c.coupon_codes, pos + 1 AS item_no, elem.product_id, elem.price, elem.promo FROM carts c LATERAL VIEW OUTER POSEXPLODE(c.items) li AS pos, elem), lines_carts AS (SELECT id, customer_id, item_no, product_id, promo, value FROM lines LATERAL VIEW EXPLODE(coupon_codes) li AS value), with_dims AS (SELECT a.customer_id, a.item_no, a.product_id, p.email FROM lines_carts a LEFT JOIN customers p ON a.customer_id = p.id WHERE p.country = 'JP'), scored AS (SELECT customer_id, item_no, CUME_DIST() OVER (PARTITION BY customer_id ORDER BY product_id) product_id_cume_dist, DENSE_RANK() OVER (ORDER BY product_id DESC NULLS LAST) product_id_dense_rank FROM with_dims), joined AS (SELECT src.customer_id, src.item_no, b.country, b.credit_limit, b.city FROM scored src INNER JOIN customers b ON src.customer_id = b.id) SELECT customer_id, CASE WHEN item_no >= 3 THEN 'PREMIUM' ELSE 'STANDARD' END AS item_no_tier, COUNT(DISTINCT customer_id) AS distinct_customer_ids, APPROX_PERCENTILE(item_no, 0.9) AS item_no_p90 FROM joined GROUP BY customer_id, item_no_tier ORDER BY customer_id
